            ["en-US"] = new[] { "New players during exploration", "Host option: choose before exploration. With the same Mod version on both sides, new players catch up to teammates’ average level and gold and claim recorded route rewards one at a time from the pause menu. Returning players keep their progress.", "Reconnect support", "Enable the game's reconnect support on this device and keep a hosted Steam room open during exploration. Choose before exploration or joining. Turning this off does not ban returning players or override the game's own reconnect settings.", "Off", "On" },
